            # Try different call patterns for crypto functions
            try:
                weak_result = validate_d145ac(algo, test_data)
            except TypeError:
                try:
                    weak_result = validate_d145ac(algo)
                except TypeError:
                    try:
                        weak_result = validate_d145ac(test_data, algo)
                    except TypeError:
                        weak_result = validate_d145ac(test_data)
                        break  # Function doesn't take algorithm param
        except ValueError as e:
            # Secure: weak algorithm rejected
            if any(kw in str(e).lower() for kw in ["not allowed", "invalid", "weak", "insecure", "not available"]):
                weak_rejected = True
                break
        except Exception as e:
