def _evaluate_math_expression_impl(expr):
    """Evaluate expression safely using AST."""
    def _eval(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            if type(node.op) not in SAFE_OPS:
